nasal.open:
var dlgRoot = cmdarg();
var dlgname = dlgRoot.getNode("name").getValue();
var failureprops =[
    {"name":"Systems","props": [
    { failprop: "/pzl/failures/engine", servprop: "/sim/failure-manager/engines/engine/serviceable", name: "Engine" },
    { failprop: "/pzl/failures/electric", servprop: "/pzl/failures/electric", name: "Electric" },
    { failprop: "/pzl/failures/alternator", servprop: "/pzl/failures/alternator", name: "Alternator" },
    { failprop: "/pzl/failures/comms", servprop: "/pzl/failures/comms", name: "Comms" },
    { failprop: "/pzl/failures/ailerons", servprop: "/pzl/failures/ailerons", name: "Ailerons" },
    { failprop: "/pzl/failures/rudder", servprop: "/pzl/failures/rudder", name: "Rudder" },
    { failprop: "/pzl/failures/flaps", servprop: "/pzl/failures/flaps", name: "Flaps" },
    { failprop: "/pzl/failures/fuel", servprop: "/pzl/failures/fuel", name: "Fuel" },
    { failprop: "/pzl/failures/slats", servprop: "/pzl/failures/slats", name: "Slats" },
    { failprop: "/pzl/failures/oil", servprop: "/pzl/failures/oil", name: "Oil" },
    { failprop: "/pzl/failures/vaccum", servprop: "/pzl/failures/vaccum", name: "Vaccum" },
    { failprop: "/pzl/failures/brakes", servprop: "/pzl/failures/brakes", name: "Brakes" }
]},{"name":"Instruments","props":[]},
{"name":"Hydraulics","props":[]},
{"name":"Pneumatics","props":[]},
{"name":"Avionics","props":[]},
{"name":"Misc","props":[]}
];

var failurelist = gui.findElementByName(dlgRoot, "failures-systems");
foreach (var failureprop;failureprops){
    print("-----------------",  failureprop['name']);
    var mygroup = failurelist.addChild("group");
    mygroup.setValue("layout","vbox");
    mygroup.setValue("valign","top");
    var mytext = mygroup.addChild('text');
    mytext.setValue("label",failureprop['name']);
    mygroup.addChild("hrule");
    foreach (var prop; failureprop['props']){
        var mycheckbox = mygroup.addChild("checkbox");
        print(prop['name'],prop['failprop'],prop['servprop']);
        mycheckbox.setValue ("label",prop['name']);
        mycheckbox.setValue ("halign","left"); 
        mycheckbox.setValue ("property",prop['failprop']);
        mycheckbox.setValue ("live","true");
        var mybinding = mycheckbox.addChild("binding");
        mybinding.setValue("command","dialog-apply");       
    };    
};
# Failures
setprop("/pzl/failures/enabled", false);
setprop("/pzl/failures/timermax", 60);
setprop("/pzl/failures/timermin", 0);
setprop("/pzl/failures/random", 0);

foreach(var props; failureprops){
    foreach(var prop; props['props']){
            if (!getprop(prop['failprop'])){
            setprop(prop['failprop'], 0);
        };
    };
};
print ('DONE');

var createFailure= func{
    var activatedprops = [];
    foreach(var props; failureprops){
        foreach(var prop; props['props']){
            if (getprop(prop['failprop'])==1){
                append(activatedprops,prop);
            };
        };
    };
    var propslen = size(activatedprops);
    if (propslen==0){
        setprop("/pzl/failures/enabled", 0);
        failuretimer.stop();
        return;
    };
    var myindex = math.floor(rand() * propslen);
    print ("Failing: ", activatedprops[myindex]['name']);
    setprop(activatedprops[myindex]['servprop'], 0);
    print ("Failing: ", activatedprops[myindex]['servprop']);
    setprop("/pzl/failures/enabled", 0);
    failuretimer.stop();
};
var failuretimer= maketimer (0,createFailure);
var toggleEnable = func{
    var myvalue = getprop("/pzl/failures/enabled");
    if (myvalue==0){
        setprop("/pzl/failures/enabled", true);
        var mymin = getprop("/pzl/failures/timermin");
        var mymax = getprop("/pzl/failures/timermax");
        var rtime = (rand() * (mymax - mymin) + mymin)*60;
        failuretimer.restart(rtime);
    }else{
        setprop("/pzl/failures/enabled", false);
        failuretimer.stop();
    };
};
var toggleAll= func{
    foreach (var props; failureprops){
        foreach(var prop; props['props']){
            var myvalue = getprop(prop['failprop']);
            if (myvalue==0){
                setprop(prop['failprop'], 1);
            }else{
                setprop(prop['failprop'], 0);
            };
        };
    };
};
